fn main() -> Int {
  let a = Vec[Int]();
  a.push(1); a.push(2);
  var total = 0;
  {
    let b = Vec[Int]();
    b.push(3); b.push(4); b.push(5);
    total = a.len() + b.len();
    // b dropped here
  }
  // a dropped here
  return total;
